#include <stdbool.h>
#include <string.h>
#include <libavcodec/avcodec.h>

// Original 16x16 red H.264 frame, generated by the recipe in ci/psp/README.md.
// Exercise the linked decoder before reporting that media support is available.
bool ir_native_psp_codec_check(void)
{
    static const unsigned char picture[] = {
        0x00,0x00,0x00,0x01,0x67,0x42,0xc0,0x0a,0xdd,0xec,0x04,0x40,0x00,0x00,0x03,0x00,
        0x40,0x00,0x00,0x03,0x00,0x83,0xc4,0x89,0xe0,0x00,0x00,0x00,0x01,0x68,0xce,0x0f,
        0x2c,0x80,0x00,0x00,0x01,0x65,0x88,0x84,0x04,0xbc,0x46,0x28,0x00,0x0a,0x8b,0xc7,
        0x00,0x01,0x28,0xd8,0xe0,0x00,0x2f,0xad,0x80,
    };
    avcodec_register_all();
    AVCodec *codec = avcodec_find_decoder(AV_CODEC_ID_H264);
    if (!codec || !avcodec_find_decoder(AV_CODEC_ID_AAC)) return false;
    AVCodecContext *context = avcodec_alloc_context3(codec);
    AVFrame *frame = av_frame_alloc();
    AVPacket packet;
    av_init_packet(&packet);
    packet.data = NULL; packet.size = 0;
    bool valid = false;
    if (!context || !frame || avcodec_open2(context, codec, NULL) < 0 ||
        av_new_packet(&packet, sizeof(picture)) < 0) goto done;
    memcpy(packet.data, picture, sizeof(picture));
    int got_frame = 0;
    if (avcodec_decode_video2(context, frame, &got_frame, &packet) < 0) goto done;
    if (!got_frame) {
        av_packet_unref(&packet);
        if (avcodec_decode_video2(context, frame, &got_frame, &packet) < 0) goto done;
    }
    valid = got_frame && frame->width == 16 && frame->height == 16 && frame->data[0] &&
            frame->data[0][0] >= 79 && frame->data[0][0] <= 83;
done:
    av_packet_unref(&packet);
    av_frame_free(&frame);
    avcodec_free_context(&context);
    return valid;
}
